; =============================================================================
; SMF Event Processor
; =============================================================================
;
; Standard MIDI File (SMF) event processing, tone generation
; dispatch, and voice channel management. Bridges SMF playback
; data to the audio engine.
; =============================================================================

	and ix, 0xff
	inc 1, ix
	cp ix, 0xff
	jr ugt, ToneGen_DispatchSubHandler
	jr ToneGen_DispatchReturn

ToneGen_DispatchSubHandler:
	push xiz
	ldda32 xiz, (4349)
	ldfr_lerp XIZ, 0x38
	pop xiz
	push_lerp 0x38
	push xiy
	pushw bc
	call DispatchHandler_JumpToSubHandler
	popw bc
	pop xiy
	pop_lerp 0x38
	push xiz
	ldto_lerp XIZ, 0x38
	stda32 4349, xiz
	pop xiz
	cpda16 xix, 0x286d
	jr ule, ToneGen_StoreBlockAndLink
	stdi8 (0x287a), 5
	jr ToneGen_DispatchReturn

ToneGen_StoreBlockAndLink:
	ldda32 xhl, (4349)
	ld (xhl + 3), ix
	ld hl, ix
	call ToneGen_ComputeBlockPtr
	ldw_d16 xwa, (3308)
	ldda32 xhl, (4349)
	ld (xhl + 1), wa
	ldw (xhl + 3), 0xffff
	stda16 (3308), xix
	lds ix, 5

ToneGen_DispatchReturn:
	ret

ToneGen_DispatchAndLinkBlock:
	push xix
	push xiy
	call DispatchHandler_JumpToSubHandler
	ld wa, ix
	ldw_d16 xhl, (0x28af)
	call ToneGen_ComputeBlockPtr
	ldda32 xhl, (4349)
	ld (xhl + 3), wa
	ld hl, wa
	call ToneGen_ComputeBlockPtr
	ldda32 xhl, (4349)
	ldw_d16 xbc, (0x28af)
	ld (xhl + 1), bc
	ldw (xhl + 3), 0xffff
	stda16 (0x28af), xwa
	stdi16 (9830), 5
	pop xiy
	pop xix
	ret

VoiceChannel_GetCombinedStatus:
	cpdi8 (4012), 6
	jr z, VoiceChannel_GetStatusBank2First
	push xix
	ld xix, 0x10d3
	lda_dri XBC, 0x07, 0xf0, 0xf4
	pop xix
	ld l, a
	push xix
	ld xix, 0x10c3
	ldb_sri A, 0x07, 0xf0, 0xf4
	pop xix
	jr VoiceChannel_CombineStatusBits

VoiceChannel_GetStatusBank2First:
	push xix
	ld xix, 0x10c3
	lda_dri XBC, 0x07, 0xf0, 0xf4
	ld xix, 0x10d3
	ldb_sri L, 0x07, 0xf0, 0xf4
	pop xix

VoiceChannel_CombineStatusBits:
	rlc_i_8 l, 2
	and l, 0x1
	sla a, 1
	or a, l
	ret

VoiceChannel_LookupParams:
	ldw_d16 xiy, (4011)
	and iy, 0xf
	push xix
	ld xix, 0x10b3
	ldb_sri L, 0x07, 0xf0, 0xf4
	pop xix
	xor h, h
	cp l, 0xff
	jr z, VoiceChannel_LookupReturn
	ld c, l
	sla hl, 2
	push xix
	ld xix, VoiceSynth_DataEntry_PtrTable
	ld_sril3 XHL, 0x07, 0xf0, 0xec
	pop xix
	ldb_sri A, 0x07, 0xec, 0xf4
	stb_d8 (4234), a
	call SoundGen_PrepareAndBuildVoice

VoiceChannel_LookupReturn:
	ret

VoiceChannel_SetPanDirection:
	call VoiceChannel_GetParamBlock
	ld w, (xiy + 4)
	and w, 0xf7
	xor a, a
	cpdi8 (4013), 64
	jr c, VoiceChannel_MergePanBit
	or a, 0x8

VoiceChannel_MergePanBit:
	or w, a
	or w, 0x10
	ld (xiy + 4), w
	ret

VoiceChannel_UpdateWithPitch:
	ldw_d16 xiy, (4011)
	and iy, 0xf
	extz xiy
	push xiy
	call SoundGen_CaptureVoiceParams
	ldb a, 0xb0
	bitda 7, (4235)
	jr z, VoiceChannel_ApplyPitchFlags
	or a, 0x2
	bitda 7, (4234)
	jr z, VoiceChannel_ApplyPitchFlags
	or a, 0x1

VoiceChannel_ApplyPitchFlags:
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jrl nz, VoiceChannel_NullRet
	sla xiy, 1
	push xix
	ld xix, 0xfae
	ldw_sri WA, 0x07, 0xf0, 0xf4
	pop xix
	srl xiy, 1
	push xiy
	call SoundGen_ScalePitchByTempo
	pop xiy
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jrl nz, VoiceChannel_NullRet
	push xix
	ld xix, SeqTrack_ChannelMapIdentity
	cpdi8 (4600), 1
	jr z, VoiceChannel_SelectChannelBank
	ld xix, SeqTrack_ChannelMapIdentity_0x10

VoiceChannel_SelectChannelBank:
	ldb_sri A, 0x07, 0xf0, 0xf4
	pop xix
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet
	ldb_d8 a, (4233)
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet
	ldb_d8 a, (4234)
	and a, 0x7f
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet
	ldb_d8 a, (4235)
	and a, 0x7f
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet
	call ToneGen_SetSustainBit
	call ToneGen_WriteChannelRegs
	stdi8 (4323), 0

VoiceChannel_NullRet:
	ret

SoundGen_ClampUpdateVoice:
	ldw_d16 xiy, (4237)
	call SoundGen_ClampVoiceIndexMin1
	and iy, 0xf
	push xiy
	call SoundGen_ReadVoiceRegs
	ldb a, 0xb0
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet2
	sla iy, 1
	push xix
	ld xix, 0xfae
	ldw_sri WA, 0x07, 0xf0, 0xf4
	pop xix
	srl iy, 1
	push xiy
	call SoundGen_ScalePitchByTempo
	pop xiy
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet2
	ldb_d8 a, (4011)
	and a, 0xf
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet2
	ldb_d8 a, (4233)
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet2
	ldb_d8 a, (4234)
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet2
	ldb_d8 a, (4235)
	push xiy
	call SoundGen_UpdateAndRefresh
	pop xiy
	cpdi8 (4323), 0
	jr nz, VoiceChannel_NullRet2
	call ToneGen_SetSustainBit
	call SoundGen_WriteVoiceParams
	stdi8 (4323), 0

VoiceChannel_NullRet2:
	ret

VoiceChannel_SetParamByte7:
	call VoiceChannel_GetParamBlock
	ldb_d8 a, (4013)
	ld w, (xiy + 7)
	and w, 0x80
	or w, a
	ld (xiy + 7), w
	ret

VoiceChannel_MergeParamByte5:
	call VoiceChannel_GetParamBlock
	ldb_d8 a, (4013)
	ld w, (xiy + 5)
	and w, 0x80
	or w, a
	ld (xiy + 5), w
	ret

SoundGen_LookupChannelBankParams:
	ldw_d16 xiy, (4011)
	and iy, 0xf
	push xix
	ld xix, 0x1093
	ldb_sri A, 0x07, 0xf0, 0xf4
	ld xix, 0x10a3
	ldb_sri W, 0x07, 0xf0, 0xf4
	pop xix
	cps a, 0
	jr nz, ToneGen_StoreBadValue
	cps w, 0
	jr c, ToneGen_StoreBadValue
	cps w, 2
	jr ugt, ToneGen_StoreBadValue
	push xix
	ld xix, 0x10b3
	lda_dri XWA, 0x07, 0xf0, 0xf4
	pop xix
	jr SoundGen_LookupReturn

ToneGen_StoreBadValue:
	ldb a, 0xff
	push xix
	ld xix, 0x10b3
	lda_dri XBC, 0x07, 0xf0, 0xf4
	pop xix

SoundGen_LookupReturn:
	ret

VoiceChannel_GetParamBlock:
	xor h, h
	ldb_d8 l, (4011)
	and l, 0xf
	sla hl, 2
	cpdi8 (4600), 1
	jr nz, VoiceChannel_GetParamBlockAlt
	push xix
	ld xix, VoiceChannel_ParamTable1
	ld_sril3 XHL, 0x07, 0xf0, 0xec
	pop xix
	jr VoiceChannel_StoreParamPtr

VoiceChannel_GetParamBlockAlt:
	push xix
	ld xix, VoiceChannel_ParamTable1_0x40
	ld_sril3 XHL, 0x07, 0xf0, 0xec
	pop xix

VoiceChannel_StoreParamPtr:
	ld xiy, xhl
	ret

VoiceChannel_ParamTable1:
	.byte 0x96, 0xf4
	nop
	nop
	ret	ov
	nop
	nop
	cp	d, b
	nop
	nop
	.byte 0xe4, 0xf4
	nop
	nop
	swi	6
	.byte 0xf4
