FileOpen:
	lda xsp, (xsp - 16)
	push xiz
	ld xbc, (xsp + 28)
	ld xwa, (xsp + 24)
	or xwa, xwa
	jrl z, FileOpen_ErrorNoFile
	lda_24 xwa, (FileClose)
	stl_da (0x0210f6), xwa
	ld (xsp + 4), 0x4
	cp (xbc), 0x0
	jr z, FileOpen_AllocBuffer

FileOpen_ParseModeLoop:
	ldb_spi A, 0xe4
	exts wa
	cp wa, 0x64
	jr z, FileOpen_ModeD
	cp wa, 0x7e
	jr z, FileOpen_ModeTilde
	cp wa, 0x62
	jr z, FileOpen_ModeB
	cp wa, 0x2b
	jr z, FileOpen_ModePlus
	cp wa, 0x61
	jr z, FileOpen_ModeA
	cp wa, 0x77
	jr z, FileOpen_ModeW
	cp wa, 0x72
	jr nz, FileOpen_ParseModeNext
	setm 0, (xsp + 4)
	jr FileOpen_ParseModeNext

FileOpen_ModeW:
	ormi8 (xsp + 4), 0x92
	jr FileOpen_ParseModeNext

FileOpen_ModeA:
	ormi8 (xsp + 4), 0x8a
	jr FileOpen_ParseModeNext

FileOpen_ModePlus:
	ormi8 (xsp + 4), 0x3
	jr FileOpen_ParseModeNext

FileOpen_ModeB:
	resm 2, (xsp + 4)
	jr FileOpen_ParseModeNext

FileOpen_ModeTilde:
	setm 5, (xsp + 4)
	jr FileOpen_ParseModeNext

FileOpen_ModeD:
	ormi8 (xsp + 4), 0x41
	resm 2, (xsp + 4)

FileOpen_ParseModeNext:
	cp (xbc), 0x0
	jr nz, FileOpen_ParseModeLoop

FileOpen_AllocBuffer:
	ld	xwa, (xsp+24)
	push	xwa
	call	16713667
	inc	1, hl
	pushw	hl
	calr	65347
	inc	6, xsp
	ld	(xsp+12), xhl
	or	xhl, xhl
	jr	nz, 5
	lds32	xhl, 0
	jrl	570
FileOpen_CopyFilename:
	ld	xwa, (xsp+24)
	push	xwa
	ld	xwa, (xsp+16)
	push	xwa
	call	16713584
	inc	8, xsp
	ld	xwa, (xsp+12)
	ld	(xsp+16), xwa
FileOpen_NormalizeName:
	ld xde, (xsp + 16)
	ld xwa, xde
	ld a, (xwa)
	extz wa
	lda_24 xbc, (CharMap_FullPermutation_0x660)
	ldb_sri A, 0x07, 0xe4, 0xe0
	bit 1, a
	jr z, FileOpen_NormalizeNoUpper
	ld xwa, (xsp + 16)
	ld a, (xwa)
	exts wa
	sub wa, 0x20
	jr FileOpen_StoreNormChar

FileOpen_ScanForColon:
	ld xwa, (xsp + 16)
	ldb_spi C, 0xe0
	ld (xsp + 16), xwa
	cp c, 0x3a
	jr nz, FileOpen_NormalizeName
	lds32 xwa, 1
	sub (xsp + 16), xwa
	ld xwa, (xsp + 16)
	stib_dsp 0xe0, 0x00
	ld (xsp + 16), xwa
	jr FileOpen_MatchDevice

FileOpen_NormalizeNoUpper:
	ld xwa, (xsp + 16)
	ld a, (xwa)
	exts wa

FileOpen_StoreNormChar:
	ld (xde), a
	cps a, 0
	jr nz, FileOpen_ScanForColon

FileOpen_MatchDevice:
	.byte 0xaf, 0x10, 0x20, 0x38, 0x1d, 0xc3, 0x07, 0xff
	.byte 0xdb, 0x8e, 0xee, 0x12, 0xaf, 0x1c, 0x20, 0x38
	.byte 0x1d, 0xc3, 0x07, 0xff, 0xef, 0x60, 0xdb, 0x88
	.byte 0xe8, 0x12, 0xaf, 0x18, 0x21, 0xbf, 0x10, 0x61
	.byte 0xaf, 0x10, 0x88, 0xaf, 0x10, 0xae, 0xbf, 0x06
	.byte 0x00, 0x00, 0xf2, 0xbc, 0xe3, 0x03, 0x30, 0xbf
	.byte 0x08, 0x60, 0x8f, 0x06, 0x21, 0xd8, 0x12, 0xd2
	.byte 0xde, 0xe3, 0x03, 0xf0, 0x69, 0x2c
FileOpen_DeviceSearchLoop:
	.byte 0xaf, 0x08, 0x20, 0xa8, 0x16, 0x20, 0x38, 0xaf
	.byte 0x10, 0x20, 0x38, 0x1d, 0x58, 0x07, 0xff, 0xef
	.byte 0x60, 0xdb, 0xd8, 0x66, 0x17, 0x8f, 0x06, 0x61
	.byte 0x40, 0x22, 0x00, 0x00, 0x00, 0xaf, 0x08, 0x88
	.byte 0x8f, 0x06, 0x21, 0xd8, 0x12, 0xd2, 0xde, 0xe3
	.byte 0x03, 0xf0, 0x61, 0xd4
FileOpen_DeviceFound:
	ld xwa, (xsp + 12)
	push xwa
	call SeqStep_FreeMemory
	inc 4, xsp
	ld a, (xsp + 6)
	extz wa
	cpda16_24 xwa, (0x3e3de)
	jr nz, FileOpen_CheckPermission

FileOpen_ErrorNoFile:
	stiw_da (0x01e53c), 0x0007
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_CheckPermission:
	ld a, (xsp + 4)
	and a, 0xf
	ld c, a
	ld xwa, (xsp + 8)
	ld a, (xwa + 1)
	extz wa
	cpl wa
	and a, c
	jr z, FileOpen_FindFreeSlot
	stiw_da (0x01e53c), 0x0002
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_FindFreeSlot:
	incdi8_24 1, (0x210f4)
	ld (xsp + 14), 0x0
	cp (xsp + 14), 0x10
	jr nc, FileOpen_SlotExhausted

FileOpen_SlotSearchLoop:
	ld a, (xsp + 14)
	extz wa
	sla wa, 2
	lda_24 xbc, (0x0210b4)
	ld_sril3 XWA, 0x07, 0xe4, 0xe0
	or xwa, xwa
	jr z, FileOpen_SlotExhausted
	incm8 1, (xsp + 14)
	cp (xsp + 14), 0x10
	jr c, FileOpen_SlotSearchLoop

FileOpen_SlotExhausted:
	cp (xsp + 14), 0x10
	jr nz, FileOpen_InitSlot
	stiw_da (0x01e53c), 0x0004
	call SeqStep_FileNopB
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_InitSlot:
	ld a, (xsp + 14)
	extz wa
	ld bc, wa
	sla bc, 2
	lda_24 xde, (0x0210b4)
	ld xwa, 0xffffffff
	stl_dri XWA, 0x07, 0xe8, 0xe4
	call SeqStep_FileNopB
	pushw 0x4b
	calr SeqStep_MemAllocWrapper
	inc 2, xsp
	ld xwa, (xsp + 8)
	ld (xwa + 30), xhl
	ld xiz, xhl
	or xiz, xiz
	jr nz, FileOpen_PopulateStruct
	ld a, (xsp + 14)
	extz wa
	ld bc, wa
	sla bc, 2
	lda_24 xde, (0x0210b4)
	lds32 xwa, 0
	stl_dri XWA, 0x07, 0xe8, 0xe4
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_PopulateStruct:
	ld a, (xsp + 14)
	ld (xiz + 5), a
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 14)
	ld (xiz + 10), xwa
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 18)
	ld (xiz + 14), xwa
	ld xwa, (xsp + 8)
	ld wa, (xwa + 12)
	ld (xiz + 8), wa
	ld xwa, (xsp + 8)
	ld (xiz + 18), xwa
	ld a, (xsp + 6)
	ld (xiz), a
	ldb_da a, (0x03e2e2)
	ld (xiz + 1), a
	ld (xiz + 2), 0xd
	ld a, (xsp + 4)
	ld (xiz + 3), a
	ei 7
	ld a, (xsp + 14)
	extz wa
	sla wa, 2
	lda_24 xbc, (0x0210b4)
	stl_dri XIZ, 0x07, 0xe4, 0xe0
	ei 6
	ld xwa, (xsp + 16)
	push xwa
	ld xwa, xiz
	push xwa
	ld xwa, (xsp + 16)
	ld xwa, (xwa + 18)
	ld xwa, (xwa)
	call (xwa)
	inc 8, xsp
	cps hl, 0
	jr z, FileOpen_ReturnHandle
	ld a, (xsp + 14)
	extz wa
	ld bc, wa
	sla bc, 2
	lda_24 xde, (0x0210b4)
	lds32 xwa, 0
	stl_dri XWA, 0x07, 0xe8, 0xe4
	ld a, l
	exts wa
	stw_da (0x01e53c), xwa
	ld xwa, xiz
	push xwa
	call SeqStep_FreeMemory
	inc 4, xsp
	lds32 xiz, 0

FileOpen_ReturnHandle:
	ld xhl, xiz

FileOpen_Return:
	pop xiz
	lda xsp, (xsp + 16)
	ret

FileRead:
	ld xbc, (xsp + 12)
	or xbc, xbc
	jr z, SeqStep_FileReadSetup
	cp (xbc + 4), 0x0
	jr nz, SeqStep_FileReadCheck

SeqStep_FileReadSetup:
	stiw_da (0x01e53c), 0x0011
	lds hl, 0
